    pub fn toShared(self: *Self, used: usize) !SharedBuffer {
        const storage: *BufferStorage = @ptrCast(self.raw().ptr);
        storage.* = .{
            .allocator = self.allocator,
            .data = self.raw(),
            .ref_count = std.atomic.Value(u32).init(1),
            .release_fn = BufferStorage.releaseDefault,
